// Reproducible jars: sorted entries and a fixed entry timestamp, so identical source gives identical bytes.
// Pure helpers (no JDK needed) so they can be unit-tested; server.js runs the `jar` tool with these arguments.

const JAR_DATE = "2026-01-01T00:00:00Z"; // any constant works; it only has to never change

/** Entries in a stable order; META-INF/MANIFEST.MF is left to the jar tool. */
function jarEntries(relPaths) {
  return [...relPaths].filter((p) => p && !p.startsWith("META-INF/MANIFEST.MF")).sort();
