// Version-support registry: structure, honesty (fail closed), and consistency with the lists the build service uses.
// Pure: no DB, no network. Run: tsx --test test/cyrus-version-registry.test.ts
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import { VERSIONS, getVersion, buildableVersions, hasCapability, resourcePackFormat } from "../lib/cyrus/versions/registry";
import { buildPack, packFormatFor } from "../lib/cyrus/textures/pack";
import { MB_VERSIONS } from "../lib/modbuilder/types";
import { GLOCK as TEX } from "../lib/cyrus/textures/sample-glock";

describe("version registry", () => {
  it("has unique ids and a sane shape", () => {
    const ids = VERSIONS.map((v) => v.id);
    assert.equal(new Set(ids).size, ids.length);
    for (const v of VERSIONS) {
      assert.ok(v.javaRelease === 21 || v.javaRelease === 25, v.id);
      assert.equal(v.javaRelease, v.family === "26" ? 25 : 21, `${v.id}: Java release must match the family`);
      assert.ok(v.dataPack && v.dataPack.major > 0, `${v.id} data pack format`);
    }
  });
  it("buildable versions are exactly what the build service compiles (MB_VERSIONS), and none are preview", () => {
    assert.deepEqual(buildableVersions().map((v) => v.id).sort(), [...MB_VERSIONS].sort());
    for (const v of buildableVersions()) assert.equal(v.status, "supported", v.id);
  });
  it("26.x is preview and not buildable; a Paper coordinate is only ever an exact stable build", () => {
    for (const v of VERSIONS.filter((x) => x.family === "26")) {
      assert.equal(v.buildable, false, v.id);
      assert.equal(v.status, "preview", v.id);
      if (v.paperCoordinate) {
        assert.match(v.paperCoordinate, /^26\.[\d.]+\.build\.\d+-stable$/, `${v.id}: coordinate must be an exact -stable build`);
        assert.equal(v.paperCoordinate, `${v.id}.build.${v.paperBuild}-stable`, v.id);
        assert.match(String(v.paperServerSha256), /^[0-9a-f]{64}$/, `${v.id}: pin the server jar sha256`);
      }
    }
  });
  it("26.3 has no stable Paper build yet (Fill shows only alpha/beta), so it must stay unpinned", () => {
    const v = getVersion("26.3")!;
    assert.equal(v.paperCoordinate, null);
    assert.equal(v.paperBuild ?? null, null);
  });
  it("26.1.2 and 26.2 are pinned to the stable builds found on 2026-10-10", () => {
    assert.equal(getVersion("26.1.2")!.paperCoordinate, "26.1.2.build.74-stable");
    assert.equal(getVersion("26.2")!.paperCoordinate, "26.2.build.133-stable");
  });
  it("no pack is marked client-verified until a real client has loaded it", () => {
    for (const v of VERSIONS) assert.equal(v.resourcePackClientVerified, false, v.id);
  });
  it("capabilities follow the research (item models 1.21.4+, Dialog API 1.21.7+)", () => {
    assert.equal(hasCapability("1.21.1", "itemModelDefinitions"), false);
    assert.equal(hasCapability("1.21.4", "itemModelDefinitions"), true);
    assert.equal(hasCapability("1.21.4", "dialogApi"), false);
    assert.equal(hasCapability("1.21.8", "dialogApi"), true);
    assert.equal(hasCapability("unknown", "dialogApi"), false);
  });
});

