"use strict";
// Cyrus Test Flight (R0): pure helpers for the disposable real-server runner (runner.js).
// No I/O, no child processes: everything here is unit-tested (test/cyrus-testflight.test.ts).
// Plain CommonJS so it runs as-is on node-2 (copied next to runner.js) and in the repo tests.

const zlib = require("zlib");

const SCHEMA = 1;
/** The ordered checks. A check passes only if it actually ran and its evidence says so. */
const CHECK_IDS = ["boot_done", "plugins_enabled", "startup_log_clean", "rcon_checks", "clean_stop", "no_leaks"];
const STATUSES = ["pass", "fail", "not_run"];

/** Reserved port range for Test Flight servers (they also run in a private network namespace). */
const PORT_RANGE = { min: 47100, max: 47199 };

/**
 * Default startup-log matchers. Each hit is a problem unless an ignore pattern also matches the line.
 * Paper prints console lines as "[HH:MM:SS LEVEL]: msg" (stdout) or "[HH:MM:SS] [thread/LEVEL]: msg" (latest.log).
 */
const DEFAULT_LOG_MATCHERS = [
  { id: "level-error", pattern: "(?:^\\[[\\d:]+ (?:ERROR|FATAL)\\]|\\[[^\\]]*/(?:ERROR|FATAL)\\])", flags: "" },
  { id: "exception-header", pattern: "^\\s*(?:Caused by: )?(?:[a-zA-Z_$][\\w$]*\\.)+[\\w$]*(?:Exception|Error)(?::|$)", flags: "" },
  { id: "enable-error", pattern: "Error occurred while (?:enabling|loading|disabling) ", flags: "" },
  { id: "could-not-load", pattern: "Could not load (?:plugin )?'", flags: "" },
  { id: "datapack-error", pattern: "(?:Couldn't (?:parse|load) data file|Failed to (?:load|parse) (?:datapack|data pack|function))", flags: "i" },
];

/** Lines that are known-harmless on a headless offline test server. Kept short and specific on purpose. */
const DEFAULT_LOG_IGNORES = [];

function compileMatchers(list) {
  return (list || []).map((m) => {
    if (!m || typeof m.pattern !== "string") throw new Error("matcher needs a string pattern");
    if (m.pattern.length > 400) throw new Error(`matcher ${m.id || "?"} pattern too long`);
    return { id: String(m.id || m.pattern.slice(0, 40)), re: new RegExp(m.pattern, (m.flags || "").replace(/[^imsu]/g, "")) };
  });
}

/**
 * Scan log lines. Returns hits [{line (1-based), matcher, text}] for lines that match any matcher and no ignore.
 * `from`/`to` are 0-based line indexes (to exclusive) so callers can restrict to the startup window.
 */
function matchLog(lines, matchers, ignores, from = 0, to = lines.length) {
  const ms = compileMatchers(matchers);
  const ig = compileMatchers(ignores);
  const hits = [];
  for (let i = from; i < Math.min(to, lines.length); i++) {
    const t = lines[i];
    const m = ms.find((x) => x.re.test(t));
    if (!m) continue;
    if (ig.some((x) => x.re.test(t))) continue;
    hits.push({ line: i + 1, matcher: m.id, text: t.slice(0, 300) });
  }
  return hits;
}

/** Index of the "Done (Xs)!" line, or -1. */
function findDone(lines) {
  return lines.findIndex((l) => /Done \(([\d.,]+)s\)!/.test(l));
}
function doneSeconds(line) {
  const m = /Done \(([\d.,]+)s\)!/.exec(line || "");
  return m ? Number(m[1].replace(",", ".")) : null;
}

const stripColors = (s) => String(s).replace(/\u00a7[0-9a-fk-orx]/gi, "");

/** Minimal plugin.yml / paper-plugin.yml reader: top-level scalar keys only (name, main, version, api-version). */
function parsePluginYml(text) {
  const out = {};
  for (const raw of String(text).split(/\r?\n/)) {
    const m = /^([A-Za-z][\w-]*):[ \t]*(.*)$/.exec(raw);
    if (!m) continue;
    let v = m[2].replace(/\s+#.*$/, "").trim();
    if (/^(['"]).*\1$/.test(v)) v = v.slice(1, -1);
    if (["name", "main", "version", "api-version"].includes(m[1]) && v) out[m[1]] = v;
  }
  return out;
}

/** Read one entry from a zip/jar buffer via its central directory (stored or deflated). null if absent. */
function readZipEntry(buf, wanted) {
  let eocd = -1;
  for (let i = buf.length - 22; i >= Math.max(0, buf.length - 65557); i--) {
    if (buf.readUInt32LE(i) === 0x06054b50) { eocd = i; break; }
  }
  if (eocd < 0) throw new Error("not a zip file (no end of central directory)");
  const count = buf.readUInt16LE(eocd + 10);
  let p = buf.readUInt32LE(eocd + 16);
  for (let n = 0; n < count; n++) {
    if (buf.readUInt32LE(p) !== 0x02014b50) throw new Error("corrupt zip central directory");
    const method = buf.readUInt16LE(p + 10);
    const csize = buf.readUInt32LE(p + 20);
    const nlen = buf.readUInt16LE(p + 28), elen = buf.readUInt16LE(p + 30), clen = buf.readUInt16LE(p + 32);
    const local = buf.readUInt32LE(p + 42);
    const name = buf.toString("utf8", p + 46, p + 46 + nlen);
    if (name === wanted) {
      if (buf.readUInt32LE(local) !== 0x04034b50) throw new Error("corrupt zip local header");
      const start = local + 30 + buf.readUInt16LE(local + 26) + buf.readUInt16LE(local + 28);
      const data = buf.subarray(start, start + csize);
      if (method === 0) return Buffer.from(data);
      if (method === 8) return zlib.inflateRawSync(data, { maxOutputLength: 4 * 1024 * 1024 });
      throw new Error(`unsupported zip method ${method}`);
    }
    p += 46 + nlen + elen + clen;
  }
  return null;
}

/** Plugin descriptor from a jar buffer: plugin.yml first, paper-plugin.yml as fallback. */
function pluginMeta(buf) {
  for (const f of ["plugin.yml", "paper-plugin.yml"]) {
    const e = readZipEntry(buf, f);
    if (e) {
      const y = parsePluginYml(e.toString("utf8"));
      return { descriptor: f, name: y.name || null, main: y.main || null, version: y.version || null, apiVersion: y["api-version"] || null };
    }
  }
  return { descriptor: null, name: null, main: null, version: null, apiVersion: null };
}

const esc = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");

/**
 * What the server log says about one plugin. `enabled` needs the "Enabling <name> v" line and no enable error and no
 * "Disabling <name>" before `stopLine` (Paper disables a plugin whose onEnable threw).
 */
function pluginLogStatus(lines, name, stopLine = lines.length) {
  const n = esc(name);
  const ev = [];
  let enabling = -1, enableErr = -1, loadErr = -1, disabled = -1;
  for (let i = 0; i < Math.min(stopLine, lines.length); i++) {
    const l = lines[i];
    if (enabling < 0 && new RegExp(`\\] Enabling ${n} v`).test(l)) { enabling = i; ev.push(`L${i + 1}: ${l.slice(0, 240)}`); }
    if (enableErr < 0 && new RegExp(`Error occurred while enabling ${n}\\b`).test(l)) { enableErr = i; ev.push(`L${i + 1}: ${l.slice(0, 240)}`); }
    if (loadErr < 0 && new RegExp(`(?:Could not load|Error occurred while loading).*${n}`).test(l)) { loadErr = i; ev.push(`L${i + 1}: ${l.slice(0, 240)}`); }
    if (disabled < 0 && enabling >= 0 && new RegExp(`\\] Disabling ${n} v`).test(l)) { disabled = i; ev.push(`L${i + 1}: ${l.slice(0, 240)}`); }
  }
  const enabled = enabling >= 0 && enableErr < 0 && loadErr < 0 && disabled < 0;
  return { enabled, sawEnabling: enabling >= 0, enableError: enableErr >= 0, loadError: loadErr >= 0, disabledBeforeStop: disabled >= 0, evidence: ev };
}

/**
 * Parse the `plugins` command reply. Paper colours enabled plugins green (§a) and disabled ones red (§c).
 * Returns {name: true|false|null} (null = listed but colour unknown).
 */
function parsePluginList(reply) {
  const out = {};
  const text = String(reply);
  // Names follow "- " or ", " in the listing; capture an optional colour code just before the name.
  const re = /(?:^|[\n,-]\s*)((?:\u00a7[0-9a-fk-or])*)([A-Za-z0-9_][A-Za-z0-9_.-]{0,63})(?=\u00a7|,|\n|$)/g;
  const listing = text.split(/\n/).filter((l) => /^\s*-\s|,/.test(stripColors(l)) || /^\s*(?:\u00a7.)*-/.test(l)).join("\n");
  let m;
  while ((m = re.exec(listing))) {
    const codes = m[1].toLowerCase();
    const name = m[2];
    if (/^(Server|Bukkit|Paper|Plugins)$/.test(name)) continue;
    out[name] = codes.includes("\u00a7a") ? true : codes.includes("\u00a7c") ? false : null;
  }
  return out;
}

/** Evaluate one RCON check against a reply (colour codes stripped). */
