// REAL Test Flight runs on node-2 (not part of the unit suite: it boots real Paper servers over ssh).
//   tsx test/cyrus-testflight-real.ts [good|broken|v12111|v2612|lock|all] [--out file.json]
// Fixtures: services/modbuilder/tools/testflight/fixtures (jars built on node-2 with fixtures/build.sh, see DOCUMENTATION.md
// "Cyrus Test Flight (R0)"); HelloR0 is the R0 26.x-lane plugin from /tank/nxeon-build/tmp/r0-26x.
import { writeFileSync } from "node:fs";
import path from "node:path";
import { runTestFlight, type RunResult } from "../lib/cyrus/testflight/client";
import { describe } from "../lib/cyrus/testflight/summary";
import type { TestFlightSpec } from "../lib/cyrus/testflight/types";

const FX = "/tank/nxeon-build/tmp/testflight/inbox/fx";
const DP = path.join(__dirname, "../services/modbuilder/tools/testflight/fixtures/datapack-tf_smoke");

const specs: Record<string, TestFlightSpec> = {
  good: {
    version: "26.2",
    plugins: [{ remotePath: `${FX}/HelloR0-26.2.jar` }],
    datapacks: [{ name: "tf_smoke", localPath: DP }],
    rcon: [
      { id: "plugin-command", command: "hellor0", expect: ["Hello from R0"] },
      { id: "plugins-listed", command: "plugins", expect: ["HelloR0"] },
      { id: "datapack-function", command: "function tf:hello", expect: ["tf:hello"] },
      { id: "help-lists-plugin", command: "help", expect: ["HelloR0"] },
    ],
  },
  broken: {
    version: "26.2",
    plugins: [{ remotePath: `${FX}/TfBroken-26.2.jar` }],
    rcon: [{ id: "plugins-listed", command: "plugins", expect: ["TfBroken"] }],
  },
  v12111: {
    version: "1.21.11",
    plugins: [{ remotePath: `${FX}/TfHello-1.21.11.jar` }],
    datapacks: [{ name: "tf_smoke", localPath: DP }],
    rcon: [
      { id: "plugin-command", command: "tfhello", expect: ["TfHello says hi on 1.21.11"] },
      { id: "datapack-function", command: "function tf:hello", expect: ["tf:hello"] },
    ],
  },
  v2612: { version: "26.1.2", rcon: [{ id: "help", command: "help", expect: ["Help"] }] },
};

const brief = (name: string, r: RunResult) => ({
  name, version: r.report.version, status: r.report.status, overall: r.summary.overall, success: r.summary.success,
  bootMs: r.report.bootMs, doneReportedSec: r.report.doneReportedSec, peakRssKb: r.report.peakRssKb, timings: r.report.timings,
  checks: r.report.checks.map((c) => ({ id: c.id, status: c.status, required: c.required, evidence: c.evidence })),
  summary: r.summary, line: describe(r.summary), notes: r.report.notes, engine: r.report.engine, artifacts: r.report.artifacts,
});

async function main() {
  const which = process.argv[2] ?? "all";
  const outIdx = process.argv.indexOf("--out");
  const out: unknown[] = [];
  const names = which === "all" ? ["good", "broken", "v12111", "v2612", "lock"] : [which];
  for (const n of names) {
    if (n === "lock") {
      // Two flights at once: exactly one may run, the other must come back "busy" without starting a server.
      const [a, b] = await Promise.all([runTestFlight(specs.v2612), new Promise<RunResult>((r) => setTimeout(() => r(runTestFlight(specs.v2612)), 4000))]);
      out.push(brief("lock-first", a), brief("lock-second", b));
      console.log("lock:", a.summary.overall, "/", b.summary.overall);
      continue;
    }
    const r = await runTestFlight(specs[n]);
    out.push(brief(n, r));
    console.log(`${n}: ${describe(r.summary)}`);
  }
  const file = outIdx > 0 ? process.argv[outIdx + 1] : null;
  if (file) writeFileSync(file, JSON.stringify(out, null, 1));
  else console.log(JSON.stringify(out, null, 1));
}
main().catch((e) => { console.error(e); process.exit(1); });

