// Cyrus Test Flight (R0): pure tests for spec validation/resolution, the verdict rules, the runner's log matcher and
// parsers, and the invoker with a fake transport. No ssh, no JVM. Run: tsx --test test/cyrus-testflight.test.ts
// The real node-2 runs live in test/cyrus-testflight-real.ts (not part of this suite).
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import zlib from "node:zlib";
import { validateSpec, resolveSpec, requiredStages } from "../lib/cyrus/testflight/spec";
import { summarize, mergeSummaries, describe as describeSummary } from "../lib/cyrus/testflight/summary";
import { runTestFlight, tarball, shq, type Remote } from "../lib/cyrus/testflight/client";
import type { CheckResult, TestFlightReport, TestFlightSpec } from "../lib/cyrus/testflight/types";
import { CHECK_IDS } from "../lib/cyrus/testflight/types";
// eslint-disable-next-line @typescript-eslint/no-require-imports
const L = require("../services/modbuilder/tools/testflight/lib.js");

const ROOT = "/tank/nxeon-build/tmp/testflight";
const allPass = (over: Partial<Record<string, Partial<CheckResult>>> = {}): CheckResult[] =>
  CHECK_IDS.map((id) => ({ id, status: "pass", required: true, evidence: [`${id} ok`], durationMs: 1, ...(over[id] ?? {}) }) as CheckResult);
const report = (checks: CheckResult[], over: Partial<TestFlightReport> = {}): TestFlightReport => ({
  schema: 1, runId: "tf-test-1", status: "completed", version: "26.2", javaRelease: 25, startedAt: "", finishedAt: "", checks,
  timings: {}, bootMs: 10000, doneReportedSec: 9, peakRssKb: 800000, artifacts: [], engine: null, notes: [], overall: "passed", ...over,
});
const SPEC: TestFlightSpec = { version: "26.2", plugins: [{ remotePath: `${ROOT}/inbox/fx/A.jar` }], rcon: [{ command: "plugins", expect: ["A"] }] };

describe("spec validation (fails closed on the registry)", () => {
  it("accepts a pinned version and resolves JDK + Paper pins from the registry", () => {
    const v = validateSpec(SPEC);
    assert.equal(v.ok, true);
    const r = resolveSpec({ ...SPEC, plugins: [{ localPath: "/x/My.jar" }] }, { runId: "tf-abc-123" });
    assert.equal(r.javaRelease, 25);
    assert.equal(r.paper.build, 133);
    assert.match(r.paper.sha256, /^bf1dcf62/);
    assert.equal(r.plugins[0].path, `${ROOT}/inbox/tf-abc-123/My.jar`);
    assert.equal(r.memory.xmxMb, 1024);
    assert.deepEqual(r.timeouts, { bootSec: 180, rconSec: 10, stopSec: 45, totalSec: 420 });
    const o = resolveSpec({ version: "1.21.11" }, { runId: "tf-abc-124" });
    assert.equal(o.javaRelease, 21);
    assert.equal(o.paper.build, 132);
  });
  it("refuses unknown versions and versions without a pinned Paper server jar", () => {
    for (const version of ["1.20.4", "26.3", "1.21.1", "26.2-SNAPSHOT"]) {
      const v = validateSpec({ version });
      assert.equal(v.ok, false, version);
    }
    assert.throws(() => resolveSpec({ version: "26.3" }, { runId: "tf-abc-125" }), /no pinned Paper server/);
  });
  it("rejects malformed specs with specific reasons", () => {
    const v = validateSpec({
      version: "26.2",
      plugins: [{ localPath: "/a.jar", remotePath: "/b.jar" } as never, { localPath: "/c.zip" }],
      datapacks: [{ name: "Bad Name", localPath: "/d" }],
