    for (const s of ["exactly one of localPath or remotePath", "must be a .jar", "name must be", "reserved for the runner", "one line", "logMatchers[0]", "xmxMb", "timeouts.bootSec", "unknown stage"]) assert.match(e, new RegExp(s.replace(/[.[\]]/g, "\\$&")), s);
    assert.equal(validateSpec({ version: "26.2", logMatchers: [] }).ok, false, "an empty matcher list would make the log check vacuous");
  });
  it("required stages follow what the spec asks for", () => {
    assert.deepEqual([...requiredStages({ version: "26.2" })].sort(), ["boot_done", "clean_stop", "no_leaks", "startup_log_clean"]);
    assert.ok(requiredStages(SPEC).has("plugins_enabled"));
