describe("summary rules", () => {
  it("passes only when every required check passed with evidence", () => {
    const s = summarize(SPEC, report(allPass()));
    assert.equal(s.overall, "passed");
    assert.equal(s.success, true);
    assert.match(describeSummary(s), /passed on Paper 26.2/);
  });
  it("a required stage that did not run is NOT success (incomplete)", () => {
    const s = summarize(SPEC, report(allPass({ rcon_checks: { status: "not_run", evidence: [] } })));
    assert.equal(s.overall, "incomplete");
    assert.equal(s.success, false);
    assert.deepEqual(s.skippedRequired, ["rcon_checks"]);
    assert.doesNotMatch(describeSummary(s), /passed/);
  });
  it("a pass without evidence counts as not run", () => {
    const s = summarize(SPEC, report(allPass({ clean_stop: { evidence: [] } })));
    assert.equal(s.overall, "incomplete");
    assert.ok(s.reasons.some((r) => /claimed pass without evidence/.test(r)));
  });
  it("a check missing from the report, or one the runner marked optional, is still required by the spec", () => {
    const missing = summarize(SPEC, report(allPass().filter((c) => c.id !== "no_leaks")));
    assert.equal(missing.overall, "incomplete");
    assert.ok(missing.reasons.some((r) => /no_leaks missing/.test(r)));
    const relabelled = summarize(SPEC, report(allPass({ plugins_enabled: { status: "not_run", required: false, evidence: [] } })));
    assert.equal(relabelled.overall, "incomplete");
  });
  it("a required failure wins over skips; optional stages do not block", () => {
    const s = summarize(SPEC, report(allPass({ plugins_enabled: { status: "fail", evidence: ["X: NOT enabled"] }, rcon_checks: { status: "not_run", evidence: [] } })));
    assert.equal(s.overall, "failed");
    const noPlugins = summarize({ version: "26.2" }, report(allPass({ plugins_enabled: { status: "not_run", required: false, evidence: [] }, rcon_checks: { status: "not_run", required: false, evidence: [] } })));
    assert.equal(noPlugins.overall, "passed");
    assert.deepEqual(noPlugins.notRunOptional, ["plugins_enabled", "rcon_checks"]);
  });
  it("busy, errored or wrong-version reports are never success, whatever their checks say", () => {
    assert.equal(summarize(SPEC, report(allPass(), { status: "busy" })).overall, "busy");
    assert.equal(summarize(SPEC, report(allPass(), { status: "error", notes: ["boom"] })).overall, "error");
    assert.equal(summarize(SPEC, report(allPass(), { version: "26.1.2" })).overall, "error");
    assert.equal(summarize(SPEC, report(allPass({ boot_done: { status: "weird" as never } }))).overall, "incomplete");
  });
  it("merging versions: worst wins, success only if all passed", () => {
    const ok = summarize(SPEC, report(allPass()));
    const bad = summarize(SPEC, report(allPass({ boot_done: { status: "fail", evidence: ["no Done"] } })));
    assert.equal(mergeSummaries([ok, ok]).success, true);
    assert.equal(mergeSummaries([ok, bad]).overall, "failed");
    assert.equal(mergeSummaries([]).success, false);
  });
});

