});

describe("summary rules", () => {
  it("passes only when every required check passed with evidence", () => {
    const s = summarize(SPEC, report(allPass()));
    assert.equal(s.overall, "passed");
    assert.equal(s.success, true);
    assert.match(describeSummary(s), /passed on Paper 26.2/);
  });
  it("a required stage that did not run is NOT success (incomplete)", () => {
    const s = summarize(SPEC, report(allPass({ rcon_checks: { status: "not_run", evidence: [] } })));
    assert.equal(s.overall, "incomplete");
    assert.equal(s.success, false);
    assert.deepEqual(s.skippedRequired, ["rcon_checks"]);
    assert.doesNotMatch(describeSummary(s), /passed/);
  });
  it("a pass without evidence counts as not run", () => {
    const s = summarize(SPEC, report(allPass({ clean_stop: { evidence: [] } })));
    assert.equal(s.overall, "incomplete");
    assert.ok(s.reasons.some((r) => /claimed pass without evidence/.test(r)));
  });
  it("a check missing from the report, or one the runner marked optional, is still required by the spec", () => {
    const missing = summarize(SPEC, report(allPass().filter((c) => c.id !== "no_leaks")));
    assert.equal(missing.overall, "incomplete");
    assert.ok(missing.reasons.some((r) => /no_leaks missing/.test(r)));
    const relabelled = summarize(SPEC, report(allPass({ plugins_enabled: { status: "not_run", required: false, evidence: [] } })));
    assert.equal(relabelled.overall, "incomplete");
  });
  it("a required failure wins over skips; optional stages do not block", () => {
    const s = summarize(SPEC, report(allPass({ plugins_enabled: { status: "fail", evidence: ["X: NOT enabled"] }, rcon_checks: { status: "not_run", evidence: [] } })));
    assert.equal(s.overall, "failed");
    const noPlugins = summarize({ version: "26.2" }, report(allPass({ plugins_enabled: { status: "not_run", required: false, evidence: [] }, rcon_checks: { status: "not_run", required: false, evidence: [] } })));
    assert.equal(noPlugins.overall, "passed");
    assert.deepEqual(noPlugins.notRunOptional, ["plugins_enabled", "rcon_checks"]);
  });
  it("busy, errored or wrong-version reports are never success, whatever their checks say", () => {
    assert.equal(summarize(SPEC, report(allPass(), { status: "busy" })).overall, "busy");
    assert.equal(summarize(SPEC, report(allPass(), { status: "error", notes: ["boom"] })).overall, "error");
    assert.equal(summarize(SPEC, report(allPass(), { version: "26.1.2" })).overall, "error");
    assert.equal(summarize(SPEC, report(allPass({ boot_done: { status: "weird" as never } }))).overall, "incomplete");
  });
  it("merging versions: worst wins, success only if all passed", () => {
    const ok = summarize(SPEC, report(allPass()));
    const bad = summarize(SPEC, report(allPass({ boot_done: { status: "fail", evidence: ["no Done"] } })));
    assert.equal(mergeSummaries([ok, ok]).success, true);
    assert.equal(mergeSummaries([ok, bad]).overall, "failed");
    assert.equal(mergeSummaries([]).success, false);
  });
});

describe("runner log matcher and parsers (lib.js)", () => {
  const log = [
    "[04:51:13 INFO]: Starting minecraft server version 26.2",
    "[04:51:13 ERROR]: Failed to request yggdrasil public key",
    "com.mojang.authlib.exceptions.MinecraftClientException: Failed to read from https://api.minecraftservices.com/publickeys",
    "Caused by: java.net.UnknownHostException: api.minecraftservices.com",
    "[04:59:46 INFO]: [TfBroken] Enabling TfBroken v1.0.0",
    "[04:59:46 ERROR]: Error occurred while enabling TfBroken v1.0.0 (Is it up to date?)",
    "java.lang.IllegalStateException: TfBroken deliberately failed in onEnable",
    "\tat dev.nxeon.tf.broken.BrokenPlugin.onEnable(BrokenPlugin.java:10) ~[TfBroken.jar:?]",
    "[04:59:46 INFO]: [TfBroken] Disabling TfBroken v1.0.0",
    "[04:59:46 INFO]: [Good] Enabling Good v2.1",
    "[05:00:00] [Server thread/ERROR]: latest.log style error line",
    "[04:59:47 INFO]: Done (8.961s)! For help, type \"help\"",
    "[04:59:48 ERROR]: after startup",
  ];
  it("flags real errors and exception headers, ignores the declared sandbox noise, respects the window", () => {
    const done = L.findDone(log);
    assert.equal(done, 11);
    assert.equal(L.doneSeconds(log[done]), 8.961);
    const { hits, ignored } = L.matchLogDetailed(log, L.DEFAULT_LOG_MATCHERS, L.DEFAULT_LOG_IGNORES, 0, done + 1);
    assert.deepEqual(hits.map((h: { line: number }) => h.line), [6, 7, 11]);
    assert.equal(hits[0].matcher, "level-error");
    assert.equal(hits[1].matcher, "exception-header");
    assert.equal(ignored.length, 3);
    assert.equal(L.matchLog(log, L.DEFAULT_LOG_MATCHERS, [], 0, done + 1).length, 6, "without ignores the sandbox lines count");
    assert.equal(L.matchLog(log, L.DEFAULT_LOG_MATCHERS, L.DEFAULT_LOG_IGNORES, done + 1).length, 1, "after-Done window");
    assert.equal(L.matchLog(["\tat foo.Bar.baz(Bar.java:1)", "[1:2 WARN]: hmm"], L.DEFAULT_LOG_MATCHERS, []).length, 0, "frames and warnings are not hits");
    assert.equal(L.matchLog(["custom BOOM here"], [{ id: "boom", pattern: "boom", flags: "i" }], []).length, 1);
  });
  it("plugin state from the log: a plugin that threw in onEnable is not enabled", () => {
    const b = L.pluginLogStatus(log, "TfBroken");
    assert.equal(b.enabled, false);
    assert.equal(b.enableError, true);
    assert.equal(b.disabledBeforeStop, true);
    assert.equal(L.pluginLogStatus(log, "Good").enabled, true);
    assert.equal(L.pluginLogStatus(log, "Missing").enabled, false);
    assert.equal(L.pluginLogStatus(["[x INFO]: [A.B] Enabling A.B v1"], "AxB").enabled, false, "names are matched literally");
  });
  it("parses the coloured `plugins` reply (green = enabled, red = disabled)", () => {
    const reply = "\u2139 Server Plugins (2):\n\u00a76Bukkit Plugins:\n \u00a72- \u00a7aHelloR0\u00a7f, \u00a7cTfBroken\n";
    assert.deepEqual(L.parsePluginList(reply), { HelloR0: true, TfBroken: false });
  });
  it("RCON expectations ignore colour codes; wire format round-trips", () => {
    assert.equal(L.evalRcon({ expect: ["Hello from R0"] }, "\u00a7aHello from \u00a7lR0").ok, true);
    const r = L.evalRcon({ expect: ["x"], expectNot: ["Unknown command"] }, "Unknown command. y");
    assert.deepEqual([r.ok, r.missing, r.forbidden], [false, ["x"], ["Unknown command"]]);
    const buf = Buffer.concat([L.rconPacket(7, 2, "datapack list"), L.rconPacket(8, 0, "h\u00e9")]);
    const { packets, rest } = L.rconParse(Buffer.concat([buf, buf.subarray(0, 5)]));
    assert.deepEqual(packets, [{ id: 7, type: 2, body: "datapack list" }, { id: 8, type: 0, body: "h\u00e9" }]);
    assert.equal(rest.length, 5);
  });
  it("server.properties: loopback only, RCON on, offline, escaped values, resource pack only when given", () => {
    const p = L.serverProperties({ port: 47101, rconPort: 47102, rconPassword: "a=b:c" });
    assert.match(p, /^server-ip=127\.0\.0\.1$/m);
    assert.match(p, /^enable-rcon=true$/m);
    assert.match(p, /^online-mode=false$/m);
    assert.match(p, /^rcon\.password=a\\=b\\:c$/m);
    assert.doesNotMatch(p, /resource-pack=/);
    assert.match(L.serverProperties({ port: 1, rconPort: 2, rconPassword: "x", resourcePack: { url: "https://p/x.zip", sha1: "ab", required: true } }), /^require-resource-pack=true$/m);
  });
  it("ports come from the reserved range and never collide; /proc/net/tcp LISTEN parsing", () => {
    for (const r of [0, 0.5, 0.9999]) {
      const { port, rconPort } = L.pickPorts(() => r);
      assert.notEqual(port, rconPort);
      for (const x of [port, rconPort]) assert.ok(x >= L.PORT_RANGE.min && x <= L.PORT_RANGE.max);
    }
    const tcp = "  sl  local_address rem_address   st\n   0: 0100007F:B7DD 00000000:0000 0A 0\n   1: 0100007F:B7DE 0100007F:1234 01 0\n";
    assert.deepEqual([...L.listeningPorts(tcp)], [0xb7dd]);
  });
  it("reads plugin.yml from a jar (stored and deflated entries)", () => {
    const yml = Buffer.from("name: TfHello\nversion: 1.0.0\nmain: dev.nxeon.tf.hello.HelloPlugin\napi-version: \"1.21.11\"\ncommands:\n  tfhello:\n    usage: /x\n");
    for (const method of [0, 8]) {
      const meta = L.pluginMeta(zip([{ name: "a/B.class", data: Buffer.from("cafebabe") }, { name: "plugin.yml", data: yml }], method));
      assert.deepEqual(meta, { descriptor: "plugin.yml", name: "TfHello", main: "dev.nxeon.tf.hello.HelloPlugin", version: "1.0.0", apiVersion: "1.21.11" });
    }
    assert.equal(L.pluginMeta(zip([{ name: "x.txt", data: Buffer.from("x") }], 0)).name, null);
    assert.throws(() => L.pluginMeta(Buffer.from("not a zip at all, definitely not")), /not a zip/);
  });
});

describe("invoker with a fake transport", () => {
  function fakeRemote(reply: (cmd: string, input?: Buffer) => { code: number; stdout: string }) {
    const calls: { cmd: string; input?: Buffer }[] = [];
    const remote: Remote = { exec: async (cmd, o) => { calls.push({ cmd, input: o?.input }); const r = reply(cmd, o?.input); return { ...r, stderr: "" }; } };
    return { remote, calls };
  }
  const files: Record<string, Buffer> = {
    "/r/lib.js": Buffer.from("lib"), "/r/runner.js": Buffer.from("runner"), "/local/My.jar": Buffer.from("jarbytes"),
    "/dp/pack.mcmeta": Buffer.from("{}"), "/dp/data/tf/function/hello.mcfunction": Buffer.from("say hi"),
  };
  const read = (p: string) => { if (!files[p]) throw new Error(`no ${p}`); return files[p]; };
  const listDir = () => [{ rel: "pack.mcmeta", abs: "/dp/pack.mcmeta" }, { rel: "data/tf/function/hello.mcfunction", abs: "/dp/data/tf/function/hello.mcfunction" }];

  it("ships one tar (artifacts + resolved spec), runs once, parses and summarises the report", async () => {
    let sentSpec: { plugins: { path: string; sha256: string }[]; datapacks: { path: string }[] } | null = null;
    const { remote, calls } = fakeRemote((cmd, input) => {
      if (cmd.startsWith("sha256sum")) return { code: 0, stdout: "" };
      if (cmd.includes("runner.js") && cmd.includes(" run ")) {
        const names = tarNames(input!);
        assert.deepEqual(names.map((n) => n.name).sort(), ["My.jar", "dp-tf_smoke/data/tf/function/hello.mcfunction", "dp-tf_smoke/pack.mcmeta", "spec.json"]);
        sentSpec = JSON.parse(names.find((n) => n.name === "spec.json")!.data.toString());
        return { code: 0, stdout: "progress\n" + JSON.stringify(report(allPass(), { runId: "tf-fake-001" })) + "\n" };
      }
      return { code: 0, stdout: "" };
    });
    const r = await runTestFlight({ version: "26.2", plugins: [{ localPath: "/local/My.jar" }], datapacks: [{ name: "tf_smoke", localPath: "/dp" }], rcon: [{ command: "plugins" }] },
      { remote, runnerDir: "/r", runId: "tf-fake-001", readFile: read, listDir });
    assert.equal(r.summary.overall, "passed");
    assert.equal(calls.length, 3, "hash check + runner install + one run call");
    assert.ok(sentSpec);
    assert.equal(sentSpec!.plugins[0].path, `${ROOT}/inbox/tf-fake-001/My.jar`);
    assert.match(sentSpec!.plugins[0].sha256, /^[0-9a-f]{64}$/);
    const run = calls[2].cmd;
    assert.match(run, /timeout -s KILL \d+ node/);
    assert.match(run, /rm -rf -- '\/tank\/nxeon-build\/tmp\/testflight\/inbox\/tf-fake-001'/, "the inbox is always removed");
  });
  it("skips the runner upload when node-2 already has the same bytes, and reports busy honestly", async () => {
    const h = (b: Buffer) => require("node:crypto").createHash("sha256").update(b).digest("hex");
    const have = `${h(files["/r/lib.js"])}  ${ROOT}/runner/lib.js\n${h(files["/r/runner.js"])}  ${ROOT}/runner/runner.js\n`;
    const { remote, calls } = fakeRemote((cmd) => {
      if (cmd.startsWith("sha256sum")) return { code: 0, stdout: have };
      return { code: 75, stdout: JSON.stringify(report(CHECK_IDS.map((id) => ({ id, status: "not_run", required: true, evidence: [], durationMs: 0 })), { status: "busy" })) };
    });
    const r = await runTestFlight({ version: "26.1.2" }, { remote, runnerDir: "/r", runId: "tf-fake-002", readFile: read });
    assert.equal(calls.length, 2);
    assert.equal(r.summary.overall, "busy");
    assert.equal(r.summary.success, false);
  });
  it("throws on an invalid spec before touching the remote, and on a refused/missing report", async () => {
    const { remote, calls } = fakeRemote(() => ({ code: 0, stdout: "" }));
    await assert.rejects(runTestFlight({ version: "26.3" }, { remote, runnerDir: "/r", readFile: read }), /no pinned Paper server/);
    assert.equal(calls.length, 0);
    await assert.rejects(runTestFlight({ version: "26.2" }, { remote, runnerDir: "/r", runId: "tf-fake-003", readFile: read }), /runner gave no report/);
  });
  it("shell quoting and tar names are safe", () => {
    assert.equal(shq("a'b"), `'a'\\''b'`);
    assert.throws(() => tarball([{ name: "../x", data: Buffer.alloc(0) }]), /bad tar entry/);
    assert.throws(() => tarball([{ name: "/abs", data: Buffer.alloc(0) }]), /bad tar entry/);
  });
});

// ---- tiny helpers: a zip writer (for pluginMeta) and a ustar reader (for the invoker's tarball) ----
function zip(entries: { name: string; data: Buffer }[], method: 0 | 8): Buffer {
  const locals: Buffer[] = [], central: Buffer[] = [];
  let off = 0;
  for (const e of entries) {
    const body = method === 8 ? zlib.deflateRawSync(e.data) : e.data;
    const n = Buffer.from(e.name);
    const lh = Buffer.alloc(30); lh.writeUInt32LE(0x04034b50, 0); lh.writeUInt16LE(method, 8); lh.writeUInt32LE(body.length, 18); lh.writeUInt32LE(e.data.length, 22); lh.writeUInt16LE(n.length, 26);
    const ch = Buffer.alloc(46); ch.writeUInt32LE(0x02014b50, 0); ch.writeUInt16LE(method, 10); ch.writeUInt32LE(body.length, 20); ch.writeUInt32LE(e.data.length, 24); ch.writeUInt16LE(n.length, 28); ch.writeUInt32LE(off, 42);
    locals.push(lh, n, body); central.push(ch, n);
    off += 30 + n.length + body.length;
  }
  const cd = Buffer.concat(central);
  const end = Buffer.alloc(22); end.writeUInt32LE(0x06054b50, 0); end.writeUInt16LE(entries.length, 8); end.writeUInt16LE(entries.length, 10); end.writeUInt32LE(cd.length, 12); end.writeUInt32LE(off, 16);
  return Buffer.concat([...locals, cd, end]);
}
function tarNames(t: Buffer): { name: string; data: Buffer }[] {
  const out: { name: string; data: Buffer }[] = [];
  for (let p = 0; p + 512 <= t.length;) {
    const h = t.subarray(p, p + 512);
    if (h.every((b) => b === 0)) break;
    const name = h.toString("utf8", 0, 100).replace(/\0.*$/s, "");
    const size = parseInt(h.toString("utf8", 124, 136).replace(/\0.*$/s, ""), 8);
    let sum = 0; for (let i = 0; i < 512; i++) sum += i >= 148 && i < 156 ? 32 : h[i];
    assert.equal(parseInt(h.toString("utf8", 148, 154), 8), sum, `tar checksum of ${name}`);
    out.push({ name, data: t.subarray(p + 512, p + 512 + size) });
    p += 512 + Math.ceil(size / 512) * 512;
  }
  return out;
}

